 static Transform Clone(Transform src,Transform parent){var t=new GameObject(src.name).transform;t.SetParent(parent,false);t.localPosition=src.localPosition;t.localRotation=src.localRotation;t.localScale=src.localScale;var mf=src.GetComponent<MeshFilter>();var r=src.GetComponent<MeshRenderer>();if(mf&&r&&r.enabled){t.gameObject.AddComponent<MeshFilter>().sharedMesh=mf.sharedMesh;t.gameObject.AddComponent<MeshRenderer>().sharedMaterials=r.sharedMaterials;}foreach(Transform c in src)if(c.gameObject.activeSelf)Clone(c,t);return t;}
 public static string Main(){const string D="Assets/Events/NewYear/WinterTown169/";var path="Assets/Events/NewYear/NY_Castle.prefab";var o=PrefabUtility.LoadPrefabContents(path);try{var winter=o.transform.Find("WinterTown_169");if(!winter.Find("Garland_Supports")){var transforms=new List<CombineInstance>();foreach(int side in new[]{-1,1})foreach(float z in new[]{-43f,-9f,18f,45f})foreach(float x in new[]{13f,23f}){var b=GameObject.CreatePrimitive(PrimitiveType.Cube);var mf=b.GetComponent<MeshFilter>();transforms.Add(new CombineInstance{mesh=mf.sharedMesh,transform=Matrix4x4.TRS(new Vector3(side*x,2.8f,z),Quaternion.identity,new Vector3(.18f,5.6f,.18f))});UnityEngine.Object.DestroyImmediate(b);}var m=new Mesh();m.CombineMeshes(transforms.ToArray(),true,true);AssetDatabase.CreateAsset(m,D+"GarlandSupports.asset");var g=new GameObject("Garland_Supports");g.transform.SetParent(winter,false);g.AddComponent<MeshFilter>().sharedMesh=m;g.AddComponent<MeshRenderer>().sharedMaterial=AssetDatabase.LoadAssetAtPath<Material>(D+"Charcoal.mat");PrefabUtility.SaveAsPrefabAsset(o,path);AssetDatabase.SaveAssets();}}finally{PrefabUtility.UnloadPrefabContents(o);}
 var scene=EditorSceneManager.NewPreviewScene();try{var src=AssetDatabase.LoadAssetAtPath<GameObject>(path);var root=new GameObject("Static_Town_Preview");UnityEngine.SceneManagement.SceneManager.MoveGameObjectToScene(root,scene);foreach(Transform c in src.transform)if(c.gameObject.activeSelf)Clone(c,root.transform);var go=new GameObject("Camera");UnityEngine.SceneManagement.SceneManager.MoveGameObjectToScene(go,scene);var cam=go.AddComponent<Camera>();cam.scene=scene;cam.fieldOfView=48;cam.farClipPlane=1000;cam.clearFlags=CameraClearFlags.SolidColor;cam.backgroundColor=new Color(.23f,.32f,.43f);var lgo=new GameObject("Sun");UnityEngine.SceneManagement.SceneManager.MoveGameObjectToScene(lgo,scene);var light=lgo.AddComponent<Light>();light.type=LightType.Directional;light.intensity=1.2f;light.transform.rotation=Quaternion.Euler(45,-30,0);for(int i=0;i<3;i++){cam.transform.position=i==0?new Vector3(110,105,-120):(i==1?new Vector3(3,6,-25):new Vector3(13,4,6));cam.transform.LookAt(i==0?new Vector3(0,10,0):(i==1?new Vector3(23,3,-6):new Vector3(20,1.8f,-2)));var rt=new RenderTexture(1500,1100,24);var tex=new Texture2D(1500,1100,TextureFormat.RGB24,false);var prior=RenderTexture.active;try{cam.targetTexture=rt;cam.Render();RenderTexture.active=rt;tex.ReadPixels(new Rect(0,0,1500,1100),0,0);tex.Apply();System.IO.File.WriteAllBytes(i==0?"Docs/locations/previews/winter-town169-overview.png":(i==1?"Docs/locations/previews/winter-town169-street.png":"Docs/locations/previews/winter-town169-snowman.png"),tex.EncodeToPNG());}finally{cam.targetTexture=null;RenderTexture.active=prior;UnityEngine.Object.DestroyImmediate(rt);UnityEngine.Object.DestroyImmediate(tex);}}return "Rendered static mesh-only castle preview; live Play Mode scenes untouched; added 16 visual garland supports.";}finally{EditorSceneManager.ClosePreviewScene(scene);}}
